from pathlib import Path

# Create the script that seeds SHA memory from conversation logs
seed_script = """
\"\"\"
seed_harmonics.py

Extracts SHA hashes from a text corpus (chat logs, notes),
calculates deltas between entries, and applies KRR resonance model.

Seeds FoldCore-style recursive memory using harmonic principles.
\"\"\"

import hashlib
import math

HARMONIC_CONSTANT = 0.35

class SeededSHAReflector:
    def __init__(self):
        self.memory = []
        self.resonance_log = []

    def sha256(self, text):
        return hashlib.sha256(text.encode()).hexdigest()

    def delta(self, h1, h2):
        return sum(a != b for a, b in zip(h1, h2)) / len(h1)

    def krr(self, r0, feedback, t):
        return r0 * math.exp(HARMONIC_CONSTANT * feedback * t)

    def seed_from_file(self, filepath):
        with open(filepath, "r", encoding="utf-8") as f:
            lines = [line.strip() for line in f if line.strip()]

        for i, line in enumerate(lines):
            current_sha = self.sha256(line)
            if i > 0:
                prev_sha = self.memory[-1]["sha"]
                delta = self.delta(prev_sha, current_sha)
                resonance = self.krr(1.0, delta, i)
                self.resonance_log.append({
                    "line": line,
                    "sha": current_sha,
                    "delta": delta,
                    "resonance": resonance
                })
            self.memory.append({
                "line": line,
                "sha": current_sha
            })

    def dump(self):
        for item in self.resonance_log:
            print(f"[Resonance: {item['resonance']:.5f}] {item['line']}")

# Example usage:
# s = SeededSHAReflector()
# s.seed_from_file("conversation_log.txt")
# s.dump()
"""

# Write to file
seed_script_path = Path("/mnt/data/seed_harmonics.py")
seed_script_path.write_text(seed_script.strip())

seed_script_path.name

